(() => {
const TRACK = {"id": "galetiny", "site": {"body": "mars", "dem": "mars", "name": ["ゲール・クレーター", "Gale crater"], "note": ["ゲール・クレーターの底の平原（アイオリス平原）。2012年に探査車キュリオシティが着陸した平原です。ほとんど平らで、南東には高さ約5 kmのアイオリス山（シャープ山）がそびえています。", "The plain on the floor of Gale crater (Aeolis Palus), where the Curiosity rover landed in 2012. Mostly flat; Aeolis Mons (Mount Sharp), about 5 km high, rises to the south-east."]}, "track": {"body": "mars", "line": [[-38.7, 6.1], [-29.3, 3.1], [-23.5, -5], [-19.1, -14], [-17.3, -23.7], [-18.2, -33.6], [-14.2, -42.7], [-5.2, -46.4], [4.7, -46.5], [14.5, -44.9], [23.2, -40.3], [27.3, -31.3], [25, -21.6], [19.9, -13.2], [10.5, -10], [1.1, -13]], "gates": [70, 96.7, 118.2, 136.4], "title": ["着陸船ミニレース", "Tiny lander race"], "intro": ["着陸船のまわりを約90 m走る、小さなレース。光の門は船のすぐそばに立っています。4台のローバーで、門を順にくぐってゴールへ！", "A tiny race of about 90 m around the lander, its light gates right beside the ship. Four rovers: pass the gates in order to the finish!"], "button": ["着陸船ミニレース", "Tiny lander race"], "home": ["ゲール・クレーターへ", "To Gale crater"]}, "check": {"time": [5, 10], "step": 0.05}};
const RECORD = {"name": "cratercamper", "track": "galetiny", "course": "16:148.5/d1", "time": 6.13279999995234, "place": 2, "color": 0, "at": 1793934922948, "hz": 10, "b64": ""};
return (
// Adds a race track (and, if given, a built-in record) to the running game, then takes the rover there.
// TRACK and RECORD are put in front of this code by make_route.py. Works on the game's dev server (`npm run dev`),
// which serves each source file as its own module: the step imports the very modules the page uses and changes their
// tables (TRACKS, SITES, RALLY_RECORDS) in place. Nothing in the game's source changes.
// Also starts a record of the page's console errors (window.__autoErrors), read by check.js.
(async () => {
  window.__autoErrors = []
  const keep = console.error.bind(console)
  console.error = (...a) => { window.__autoErrors.push(a.map(String).join(' ')); keep(...a) }
  window.addEventListener('error', (e) => window.__autoErrors.push('uncaught: ' + e.message))
  window.addEventListener('unhandledrejection', (e) => window.__autoErrors.push('unhandled rejection: ' + e.reason))

  // The dev server adds ?t=<time> to a module changed since it started, and an import of the bare path would load a
  // second copy. So read the exact address from the code of a module that imports it.
  const addressIn = async (importer, path) => {
    const text = await (await fetch(importer)).text()
    const m = text.match(new RegExp('"(' + path.replace(/[.]/g, '\\.') + '(?:\\?[^"]*)?)"'))
    if (!m) throw new Error(`${path} is not imported by ${importer}: the game's files have moved`)
    return m[1]
  }
  const rallyAt = await addressIn('/src/debugHooks.ts', '/src/state/rally.ts')
  const rally = await import(rallyAt)
  if (rally.useRally !== window.__sv.rally.state) throw new Error(`${rallyAt} is not the page's own module`)
  const tracks = await import(await addressIn(rallyAt, '/src/data/rallyTracks.ts'))
  const surfaces = await import(await addressIn(await addressIn(rallyAt, '/src/state/landing.ts'), '/src/data/surfaces.ts'))
  const records = await import(await addressIn('/src/state/rallyHiscore.ts', '/src/data/rallyRecords.ts'))

  const id = TRACK.id
  if (tracks.TRACKS[id] || surfaces.SITES[id]) throw new Error(`the game already has a track or site named ${id}`)
  surfaces.SITES[id] = TRACK.site
  tracks.TRACKS[id] = TRACK.track
  if (RECORD) {
    if (RECORD.track !== id) throw new Error(`the record is for track ${RECORD.track}, not ${id}`)
    records.RALLY_RECORDS.push(RECORD) // before the table of this track is first read: the game reads it once
  }
  window.__autoTrack = TRACK.track
  rally.goToRally(id)
  return `track ${id} added (${TRACK.track.line.length} points, ${TRACK.track.gates.length} gates)` +
    (RECORD ? `, record of ${RECORD.name} ${RECORD.time} s` : ', no record')
})()
)
})()

(() => {
const STEP = 0.05;
return (
// A fixed time step for the race, so that the time on the result card is the time the game simulated, the same on a
// fast machine and a slow one. The game's frame step (three.js's Clock) and its race timer (rallyNow in
// src/state/rally.ts) both read performance.now(). The game caps a frame's step at 0.05 s (Math.min(rawDt, 0.05) in
// Rover.tsx and Rally.tsx), so in a software-rendered browser drawing about one frame per second it simulates 0.05 s
// per frame while the race timer counts real seconds: a 7 s lap once read 2:44.6.
// Installed before Start. From then on performance.now() changes only once per drawn frame: until the race runs it
// follows real time; from the first frame of the race it advances exactly STEP seconds per frame (STEP, the track's
// check.step, is put in front of this code by make_route.py), so the rover, the rivals and the timer all take steps of
// STEP. Within a frame the clock stands still, so the game's loops that work "for up to N ms per frame" (ground tiles)
// finish their work in that frame.
(() => {
  if (window.__autoClock) throw new Error('the fixed-step clock is already installed')
  if (!(STEP > 0 && STEP <= 0.05)) throw new Error(`STEP must be in (0, 0.05] s (the game caps a frame at 0.05 s), not ${STEP}`)
  const real = performance.now.bind(performance)
  const rally = window.__sv.rally.state
  const C = (window.__autoClock = { step: STEP, now: real(), frames: 0, realAtRun: null, real })
  performance.now = () => C.now
  const tick = () => {
    if (C.realAtRun === null && rally.getState().phase === 'run') C.realAtRun = real()
    if (C.realAtRun !== null) {
      C.now += STEP * 1000
      C.frames++
    } else C.now = Math.max(C.now, real())
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
  return `clock: real time until the race runs, then ${STEP} s per frame`
})()
)
})()

// The player's rover driven along the race line on the app's own frames (requestAnimationFrame), for the length of
// one race. Pure pursuit on the course line: look-ahead 5 m + 0.45 s x speed; speed from the bends ahead and the
// rover's turning radius R = 2.6 + 0.32 v (src/components/surface/Rover.tsx).
// Reads the line from window.__autoTrack (set by the step that adds the track). Drives only while the race runs;
// window.__pilot says what it did. An error stops it and goes to console.error.
(() => {
  const line = window.__autoTrack?.line
  if (!line) throw new Error('pilot: window.__autoTrack.line is not set (add the track first)')
  const pts = line.map(([x, z]) => ({ x, z }))
  const len = [0]
  for (let i = 1; i < pts.length; i++) len.push(len[i - 1] + Math.hypot(pts[i].x - pts[i - 1].x, pts[i].z - pts[i - 1].z))
  const total = len[len.length - 1]
  const at = (s) => {
    const ss = Math.min(Math.max(s, 0), total)
    let i = 0
    while (i < pts.length - 2 && len[i + 1] < ss) i++
    const a = pts[i], b = pts[i + 1], seg = len[i + 1] - len[i] || 1, t = (ss - len[i]) / seg
    return { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t, dx: (b.x - a.x) / seg, dz: (b.z - a.z) / seg }
  }
  const nearest = (x, z, hint) => {
    let best = hint, bestD = Infinity
    for (let i = 0; i < pts.length - 1; i++) {
      if (Math.abs(len[i] - hint) > 40) continue // a lap may pass near its own start: stay near the last place
      const a = pts[i], b = pts[i + 1], ex = b.x - a.x, ez = b.z - a.z, l2 = ex * ex + ez * ez || 1
      const t = Math.min(1, Math.max(0, ((x - a.x) * ex + (z - a.z) * ez) / l2))
      const d = (a.x + ex * t - x) ** 2 + (a.z + ez * t - z) ** 2
      if (d < bestD) { bestD = d; best = len[i] + (len[i + 1] - len[i]) * t }
    }
    return best
  }
  const wrap = (a) => { while (a > Math.PI) a -= 2 * Math.PI; while (a < -Math.PI) a += 2 * Math.PI; return a }
  const s = window.__sv, inp = s.rover.input
  const P = (window.__pilot = { frames: 0, resets: 0, vmax: 0, done: false, error: null })
  let hint = null
  const tick = () => {
    try {
      const st = s.rally.state.getState()
      if (st.phase === 'done' || st.phase === 'off') {
        Object.assign(inp, { throttle: 0, steer: 0 })
        P.done = true
        return
      }
      if (st.phase === 'run') {
        const p = s.rover.pose
        if (hint === null) hint = nearest(p.x, p.z, 45) // the grid stands 45 m down the line (Rally.tsx GRID_S)
        hint = nearest(p.x, p.z, hint)
        const v = Math.abs(p.speed)
        P.vmax = Math.max(P.vmax, v)
        const T = at(hint + 5 + 0.45 * v)
        const err = wrap(Math.atan2(-(T.x - p.x), -(T.z - p.z)) - p.heading)
        let target = 60 / 3.6
        for (let a = 0; a <= 60; a += 5) {
          const d0 = at(hint + a), d1 = at(hint + a + 10)
          const k = Math.abs(wrap(Math.atan2(d1.dz, d1.dx) - Math.atan2(d0.dz, d0.dx))) / 10
          if (k < 1e-4) continue
          const vk = Math.max(2, (0.8 / k - 2.6) / 0.32)
          target = Math.min(target, Math.sqrt(vk * vk + 2 * 8 * a))
        }
        inp.throttle = v < target - 0.3 ? 1 : v > target + 0.6 ? -1 : 0
        inp.steer = Math.max(-1, Math.min(1, -err * 4))
        if (st.lost) { inp.reset = true; P.resets++ }
        P.frames++
      }
      requestAnimationFrame(tick)
    } catch (e) {
      Object.assign(inp, { throttle: 0, steer: 0 })
      P.error = String(e)
      console.error('ERROR pilot: ' + e)
    }
  }
  requestAnimationFrame(tick)
  return 'pilot on'
})()

(() => {
const CHECK = {"time": [5, 10], "step": 0.05};
const RECORD = {"name": "cratercamper", "track": "galetiny", "course": "16:148.5/d1", "time": 6.13279999995234, "place": 2, "color": 0, "at": 1793934922948, "hz": 10, "b64": ""};
const QUALITY = "low";
return (
// The test's verdict, after the race: PASS only if the race finished with every gate passed; the time is inside
// CHECK.time (seconds); the pilot had no error and did not need the game's "back to the gate"; no console error since
// the track was added; the game drew at the pinned level QUALITY from the Start button to the finish; and, with a
// record, its name is in the result card's table. Returns the findings as JSON (the route saves them) and keeps them in
// window.__autoResult; the route's last step fails the run unless PASS.
// CHECK, RECORD and QUALITY are put in front of this code by make_route.py.
(() => {
  const st = window.__sv.rally.state.getState()
  const p = window.__pilot
  const card = document.querySelector('.rally-result')
  const out = {
    phase: st.phase, gates: `${st.gate}/${st.gates}`, time: st.result?.time ?? null, place: st.result?.place ?? null,
    pilot: p, errors: window.__autoErrors, table: card ? card.innerText : null, level: window.__autoLevel ?? null,
  }
  const C = window.__autoClock
  if (C) out.clock = { step: C.step, frames: C.frames, real_s: C.realAtRun === null ? null : (C.real() - C.realAtRun) / 1000 }
  const fail = []
  if (st.phase !== 'done' || !st.result) fail.push(`the race did not finish (phase ${st.phase})`)
  if (st.gate !== st.gates) fail.push(`gates passed ${st.gate} of ${st.gates}`)
  const [lo, hi] = CHECK.time
  if (!(st.result?.time >= lo && st.result?.time <= hi)) fail.push(`time ${st.result?.time} s is outside ${lo}-${hi} s`)
  if (p?.error) fail.push(`pilot error: ${p.error}`)
  if (p?.resets) fail.push(`the pilot was sent back to a gate ${p.resets} time(s)`)
  if (window.__autoErrors.length) fail.push(`${window.__autoErrors.length} console error(s): ${window.__autoErrors[0]}`)
  if (!C) fail.push('no fixed-step clock (clock.js): the time is real time')
  const L = window.__autoLevel
  if (!L) fail.push('no record of the drawing level (the route\'s level watch)')
  else {
    if (L.start !== QUALITY) fail.push(`the race started at level ${L.start}, not the pinned ${QUALITY}`)
    // a change of level rebuilds the rivals; after the finish ('done') it no longer matters
    const during = L.changes.filter((c) => c.phase !== 'done')
    const seen = during.map((c) => `${c.from}->${c.to} (${c.phase})`).join(', ')
    if (during.length) fail.push(`the level changed during the race: ${seen}`)
  }
  if (!card) fail.push('no result card')
  if (RECORD && !(card?.innerText ?? '').includes(RECORD.name)) fail.push(`the result card's table does not show ${RECORD.name}`)
  out.verdict = fail.length ? 'FAIL: ' + fail.join('; ') : 'PASS'
  window.__autoResult = out
  return JSON.stringify(out, null, 1)
})()
)
})()
